use serde::{Deserialize, Serialize};

use crate::EmulatorError;

/// ARMv4T execution modes. System mode shares the User register bank.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum ProcessorMode {
    /// Unprivileged execution.
    User = 0x10,
    /// Fast interrupt, with banked R8–R14.
    Fiq = 0x11,
    /// Normal interrupt.
    Irq = 0x12,
    /// Reset and software interrupt handler.
    Supervisor = 0x13,
    /// Memory abort handler (not generated by the GBA bus).
    Abort = 0x17,
    /// Undefined instruction handler.
    Undefined = 0x1b,
    /// Privileged mode sharing the User register bank.
    System = 0x1f,
}

impl ProcessorMode {
    pub(crate) fn bank(self) -> usize {
        match self {
            Self::User | Self::System => 0,
            Self::Fiq => 1,
            Self::Irq => 2,
            Self::Supervisor => 3,
            Self::Abort => 4,
            Self::Undefined => 5,
        }
    }
}

/// Current or saved processor status, restricted to valid ARMv4T modes.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProcessorStatus(u32);

impl Default for ProcessorStatus {
    fn default() -> Self {
        Self(0xd3) // Reset: ARM, Supervisor, IRQ and FIQ masked.
    }
}

impl ProcessorStatus {
    /// Validates the mode field. Reserved bits are retained for MSR/MRS fidelity.
    pub fn try_new(bits: u32) -> Result<Self, EmulatorError> {
        match bits & 0x1f {
            0x10 | 0x11 | 0x12 | 0x13 | 0x17 | 0x1b | 0x1f => Ok(Self(bits)),
            mode => Err(EmulatorError::InvalidProcessorMode(mode)),
        }
    }

    pub(crate) fn saved_bits(bits: u32) -> Self {
        Self(bits)
    }

    /// Raw status bits, including control and arithmetic flags.
    #[must_use]
    pub fn bits(self) -> u32 {
        self.0
    }

    /// The active privilege and register-banking mode.
    #[must_use]
    pub fn mode(self) -> ProcessorMode {
        match self.0 & 0x1f {
            0x10 => ProcessorMode::User,
            0x11 => ProcessorMode::Fiq,
            0x12 => ProcessorMode::Irq,
            0x13 => ProcessorMode::Supervisor,
            0x17 => ProcessorMode::Abort,
            0x1b => ProcessorMode::Undefined,
            0x1f => ProcessorMode::System,
            _ => unreachable!("ProcessorStatus constructors validate modes"),
        }
    }

    /// Whether instructions are decoded in Thumb state.
    #[must_use]
    pub fn thumb(self) -> bool {
        self.0 & 0x20 != 0
    }

    /// Whether IRQ exceptions are masked.
    #[must_use]
    pub fn irq_disabled(self) -> bool {
        self.0 & 0x80 != 0
    }

    /// N flag.
    #[must_use]
    pub fn negative(self) -> bool {
        self.0 >> 31 != 0
    }

    /// Z flag.
    #[must_use]
    pub fn zero(self) -> bool {
        self.0 & (1 << 30) != 0
    }

    /// C flag, or inverse borrow for subtraction.
    #[must_use]
    pub fn carry(self) -> bool {
        self.0 & (1 << 29) != 0
    }

    /// V flag, indicating signed arithmetic overflow.
    #[must_use]
    pub fn overflow(self) -> bool {
        self.0 & (1 << 28) != 0
    }

    pub(crate) fn set_thumb(&mut self, thumb: bool) {
        self.0 = (self.0 & !0x20) | (u32::from(thumb) << 5);
    }

    pub(crate) fn set_nz(&mut self, value: u32) {
        self.0 = (self.0 & !0xc000_0000) | (value & 0x8000_0000) | (u32::from(value == 0) << 30);
    }

    pub(crate) fn set_carry(&mut self, carry: bool) {
        self.0 = (self.0 & !(1 << 29)) | (u32::from(carry) << 29);
    }

    pub(crate) fn set_overflow(&mut self, overflow: bool) {
        self.0 = (self.0 & !(1 << 28)) | (u32::from(overflow) << 28);
    }

    pub(crate) fn condition_passed(self, condition: u32) -> bool {
        match condition {
            0 => self.zero(),
            1 => !self.zero(),
            2 => self.carry(),
            3 => !self.carry(),
            4 => self.negative(),
            5 => !self.negative(),
            6 => self.overflow(),
            7 => !self.overflow(),
            8 => self.carry() && !self.zero(),
            9 => !self.carry() || self.zero(),
            10 => self.negative() == self.overflow(),
            11 => self.negative() != self.overflow(),
            12 => !self.zero() && self.negative() == self.overflow(),
            13 => self.zero() || self.negative() != self.overflow(),
            14 => true,
            15 => false, // NV on ARMv4, not ARMv5 unconditional space.
            _ => unreachable!("condition fields contain four bits"),
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{ProcessorMode, ProcessorStatus};

    #[test]
    fn reset_state_is_arm_supervisor_with_interrupts_masked() {
        let status = ProcessorStatus::default();
        assert_eq!(status.mode(), ProcessorMode::Supervisor);
        assert!(!status.thumb());
        assert!(status.irq_disabled());
        assert_eq!(status.bits(), 0xd3);
    }

    #[test]
    fn all_conditions_match_boolean_definitions() {
        for flags in 0..16 {
            let status = ProcessorStatus::try_new((flags << 28) | 0x10).expect("valid User mode");
            let n = flags & 8 != 0;
            let z = flags & 4 != 0;
            let c = flags & 2 != 0;
            let v = flags & 1 != 0;
            let expected = [
                z,
                !z,
                c,
                !c,
                n,
                !n,
                v,
                !v,
                c && !z,
                !c || z,
                n == v,
                n != v,
                !z && n == v,
                z || n != v,
                true,
                false,
            ];
            for (condition, expected) in expected.into_iter().enumerate() {
                assert_eq!(
                    status.condition_passed(condition as u32),
                    expected,
                    "condition {condition:x}, flags {flags:x}"
                );
            }
        }
    }

    #[test]
    fn rejects_reserved_modes() {
        for bits in 0..32 {
            let valid = matches!(bits, 0x10 | 0x11 | 0x12 | 0x13 | 0x17 | 0x1b | 0x1f);
            assert_eq!(
                ProcessorStatus::try_new(bits).is_ok(),
                valid,
                "mode {bits:x}"
            );
        }
    }
}
